    private static var cache: [Logo: NSImage] = [:]

    var image: NSImage {
        if let i = Logo.cache[self] { return i }
        let img = NSImage(data: Data(svg.utf8)) ?? NSImage()
        img.size = NSSize(width: 24, height: 24)
        img.isTemplate = isTemplate
        Logo.cache[self] = img
        return img
    }
}

/// A logo at a given size; template logos take `tint`.
struct LogoView: View {
    let logo: Logo
    var size: CGFloat = 16
    var tint: Color = Theme.text
    var body: some View {
        if logo.isTemplate {
            Image(nsImage: logo.image).renderingMode(.template).resizable().interpolation(.high)
                .foregroundStyle(tint).frame(width: size, height: size)
        } else {
            Image(nsImage: logo.image).renderingMode(.original).resizable().interpolation(.high)
                .frame(width: size, height: size)
        }
    }
}
